Translate("zhCN", "valormok", {
	title = "瓦罗莫克",
	sections = {
		{
			title = "概述",
			text = [=[瓦罗莫克是{link:horde}部落{/link}在{link:azshara}艾萨拉{/link}西部的营地，位于{link:haldarr-encampment}哈达尔营地{/link}以北。这是一个孤零零的哨所，有一位双足飞龙管理员、一个铁匠和一个厨师。它曾经有十几名战士。他们中的大多数奉{link:orgrimmar}奥格瑞玛{/link}的贝尔格罗姆·碎石之命，跟随血精灵{link:magus-rimtori}瑞姆托里{/link}进入荒野，结果被她杀害了。留下来的{link:ag-tor-bloodfist}阿格图·血拳{/link}想要复仇。被派到这里作为惩罚的{link:jediga}杰迪加{/link}想要利润。两人都不指望奥格瑞玛的援助。这里的双足飞龙是部落离开艾萨拉的唯一一条快捷道路。]=],
		},
	},
})

Translate("zhCN", "ruins-of-eldarath", {
	title = "埃达拉斯废墟",
	aliases = { "埃达拉斯" },
	sections = {
		{
			title = "概述",
			text = [=[埃达拉斯是一座建在{link:bay-of-storms}风暴海湾{/link}悬崖上的上层精灵城市。世界破碎时，它的大部分坠入了大海。如今留下的，是一座由苍白石头和断裂拱门组成的迷宫，被恶鞭{link:naga}纳迦{/link}所占据。四块巨大的石板仍矗立在废墟之中，每块都以一位上层精灵巫师的名字命名，从{link:ironforge}铁炉堡{/link}到{link:undercity}幽暗城{/link}的学者们都想得到它们的拓本。沿岸的潮池已被污染。一个{link:tauren}牛头人{/link}喝了其中一个池子的水后病倒了，{link:forsaken}被遗忘者{/link}的药剂师们对这水产生了一种不健康的兴趣。]=],
		},
	},
})

Translate("zhCN", "temple-of-zin-malor", {
	title = "辛玛洛神殿",
	aliases = { "辛玛洛" },
	sections = {
		{
			title = "概述",
			text = [=[辛玛洛神殿矗立在{link:ruins-of-eldarath}埃达拉斯废墟{/link}的中心。这里曾经存放着一颗水晶，它能容纳并驾驭强大的奥术力量。偷走它的人心怀恶意，水晶碎裂了。它的守护者变成了受诅咒的灵魂，上层精灵的神圣典籍被遗弃在神殿的大厅里腐烂。如今，{link:naga}纳迦{/link}{link:warlord-krellian}军阀克雷利安{/link}以神殿为驻地，躲在一道卫兵组成的墙后，搜罗他能找到的一切魔法。纳迦守卫这座神殿，比守卫废墟的任何其他部分都更加凶猛。]=],
		},
	},
})

Translate("zhCN", "bay-of-storms", {
	title = "风暴海湾",
	sections = {
		{
			title = "概述",
			text = [=[风暴海湾是一道宽阔的灰色海湾，深深切入{link:azshara}艾萨拉{/link}的中部。这里的海水躁动不安，岛屿寥寥无几。北岸是{link:hetaera}赫塔拉{/link}的巢穴，那是一头自称这片海域统治者的三头巨兽的巢窟。{link:temple-of-arkkoran}亚考兰{/link}的龙虾人在海湾东部的水域狩猎，{link:naga}纳迦{/link}则在整片海湾的水下游弋。南边的一座小岛上，由三只地狱犬守护着，住着恶魔猎手{link:loramus-thalipedes}洛拉姆斯·萨里比迪斯{/link}。]=],
		},
	},
})

Translate("zhCN", "temple-of-arkkoran", {
	title = "亚考兰神殿",
	aliases = { "亚考兰" },
	sections = {
		{
			title = "概述",
			text = [=[亚考兰神殿矗立在{link:azshara}艾萨拉{/link}东部的水边。这里是海岸蟹人——龙虾人的家园，也是他们所侍奉的庞然大物的家园：{link:lord-arkkoroc}亚考罗克{/link}，连恶魔猎手{link:loramus-thalipedes}洛拉姆斯{/link}都称他为次等神祇。他的先知、咔嚓者和钳击者把守着通道，攻击他们发现的任何陌生人。能活着到达他面前的人可以与他讨价还价，但他总要开价，而他上一次开出的价码是用血来支付的。]=],
		},
	},
})

Translate("zhCN", "thalassian-base-camp", {
	title = "萨拉斯营地",
