		{
			title = "概述",
			text = [=[在北方半岛的峭壁上，一队血精灵扎下了营地。他们的勘测员和回收者在这片土地上搜寻上层精灵失落的宝藏，并把找到的魔法研磨成闪闪发光的粉尘。他们的首领是{link:magus-rimtori}大法师雷姆托里{/link}。她雇用了{link:orcs}兽人{/link}和一个地精来帮她，又背叛了他们。在她自己的帐篷附近，立着一圈奥术水晶，是按照一本古老召唤之书中的图样布置的。]=],
		},
	},
})

Translate("zhCN", "legashi-encampment", {
