Translate("zhCN", "shadowsong-shrine", {
	title = "影歌神殿",
	sections = {
		{
			title = "概述",
			text = [=[影歌神殿是{link:azshara}艾萨拉{/link}西部的一处废墟，位于{link:talrendis-point}塔伦迪斯营地{/link}东北。这里闹鬼。上层精灵的幽魂和小巫妖在石块间飘荡，仍然渴求着毁灭了他们的{link:arcane-magic}奥术魔法{/link}。这些灵魂对每个民族都同样构成困扰，据说他们那样的渴求会引来{link:burning-legion}燃烧军团{/link}的目光。{link:sentinels}哨兵{/link}们请求让他们从这个世界解脱。附近游荡着一个更黑暗的鬼魂，它带着{link:queen-azshara}艾萨拉女王{/link}的卫队长的名字。]=],
		},
	},
})

Translate("zhCN", "ravencrest-monument", {
	title = "拉文凯斯雕像",
	sections = {
		{
			title = "概述",
			text = [=[在{link:azshara}艾萨拉{/link}南端的悬崖上，俯临大海，躺着一座古代精灵巨像的残骸。只有它的双腿还立着。其余部分碎落在周围，或者坠入了海浪之中。它带着拉文凯斯家族的名字，但没有任何编年史记载它纪念的是谁，或者是何时建造的。如今恶鞭{link:naga}纳迦{/link}在碎块之间游荡。只能从陆地经由一座桥到达那里。]=],
		},
	},
})

Translate("zhCN", "southridge-beach", {
	title = "南山海滩",
	sections = {
		{
			title = "概述",
			text = [=[南山海滩位于{link:azshara}艾萨拉{/link}南部海岸，在蓝龙{link:azuregos}艾索雷葛斯{/link}守望的森林下方。在{link:captain-vanessa-beltis}瓦妮莎·贝蒂斯船长{/link}的率领下，{i}地平线侦察者号{/i}来到这里，寻找一处安全的锚地。太阳落山还不到一个小时，{link:naga}纳迦{/link}就袭击了她的船员。幸存者在海滩上方的一座{link:stranglethorn-vale}山谷{/link}里坚守，至今仍在那里等待，他们知道纳迦还会回来。她的一些乘客来艾萨拉是为了自己的事。]=],
		},
	},
})

Translate("zhCN", "blackmaw-hold", {
	title = "黑喉要塞",
	sections = {
		{
			title = "概述",
			text = [=[在{link:azshara}艾萨拉{/link}北部，矗立着{link:furbolgs}熊怪{/link}的一道巨门。自{link:kalimdor}卡利姆多{/link}的人们有记忆以来，它就一直紧闭着，守卫们赶走了每一个靠近的陌生人。门后是黑喉要塞，一座深深凿入山体的巨大熊怪城市。它的居民正在与一股开始在城市深处躁动的腐化作战。据说，它的隧道还向更深处延伸，通往比这座城市本身更古老的地方。]=],
		},
	},
