Translate("zhCN", "loramus-thalipedes", {
	title = "洛拉姆斯·萨里比迪斯",
	subtitle = "艾萨拉的恶魔猎手",
	found = "风暴海湾南部的一座小岛",
	hint = "在风暴海湾的岛屿中寻找那位猎杀恶魔的人。",
	allegiance = "只为自己的狩猎",
	aliases = { "洛拉姆斯" },
	sections = {
		{
			title = "概述",
			text = [=[洛拉姆斯·萨里比迪斯是一位独自住在{link:bay-of-storms}风暴海湾{/link}一座岛上的恶魔猎手。三只地狱犬守护着他：{link:farmer-ray}雷{/link}塔夫、沙希莱尔和扎曼。他没有耐心忍受打扰。然而，对于{link:burning-legion}燃烧军团{/link}在这个世界上的领主，他知道的比各王国的任何贤者都多，而且他会帮助任何愚蠢到要去猎杀他们的人。]=],
		},
		{
			title = "意义",
			text = [=[洛拉姆斯是唯一知道如何伤害{link:razelikh-the-defiler}污染者拉瑟莱克{/link}的人。他知道{link:lord-kazzak}卡扎克{/link}退入{link:the-tainted-scar}腐烂之痕{/link}的故事，知道约束拉瑟莱克三名副官的契约，也知道能够得知{link:defilers}污染者{/link}真名的仪式。没有他，对抗{link:blasted-lands}诅咒之地{/link}恶魔领主的战争根本无从打起。]=],
